        "Hebrew",
        "<strong>Olah (<em>עֹלָה</em>) — “that which goes up.”</strong> The most distinctive Israelite sacrifice: the entire animal, except the hide, is burnt on the altar — none is eaten. The name refers to the smoke ascending. Among ancient Near Eastern cultures the practice was unusual; most cultures fed sacrificial meat to the priests and worshippers. The whole-burnt offering signals total devotion — nothing is retained for human use. Distinct from the <em>zevaḥ</em> (peace offering, eaten communally) and the <em>ḥattat</em> (sin offering), the <em>‘olah</em> is the most fully Godward sacrifice. The Greek LXX rendered it <em>holokauston</em> (“wholly burnt”), the source of the English word “holocaust.”",
        "User paraphrase; references LXX",
