        "<strong>Smikhah (<em>סְמִיכָה</em>) — laying on of hands.</strong> The gesture is more than identification; the Hebrew verb <em>samakh</em> means to press or lean, suggesting the offerer transfers something to the animal. Whether what passes is sin (substitution), ownership (designation), or simply identity is debated within the rabbinic tradition itself. The same gesture later marks rabbinic ordination — the transfer of authority from teacher to student.",
