        "<strong>Dictionary (Easton's).</strong> <strong>BIRD B</strong> irds are divided in the Mosaic law into two classes, (1) the clean (Leviticus 1:14-17; 5:7-10; 14:4-7), which were offered in sacrifice; and (2) the unclean (Leviticus 11:13-20). When offered in sacrifice, they were not divided as other victims were (Genesis 15:10). They are mentioned also as an article of food (Deuteronomy 14:11). The art of snaring wild birds is referred to (Psalm 124:7; Proverbs 1:17; 7:23; Jeremiah 5:27). Singing birds are mentioned in Psalm 104:12;…",
