    (
        8,
        6,
        "b",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ABLUTION</strong> or washing, was practised, (1.) When a person was initiated into a higher state: e.g., when Aaron and his sons were set apart to the priest’s office, they were washed with water previous to their investiture with the priestly robes (Leviticus 8:6). (2.) Before the priests approached the altar of God, they were required, on pain of death, to wash their hands and their feet to cleanse them from the soil of common life (Exodus 30:17-21). To this practice the Psalmist alludes,…",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
