    (
        10,
        1,
        "",
        "strange fire",
        "comm",
        "Note",
        "Note",
        "<strong>The death of Nadab and Abihu.</strong> The Hebrew <em>esh zarah</em> (“foreign fire”) is undefined — perhaps incense kindled from non-altar coals, perhaps a wrong recipe, perhaps an unauthorized timing. Multiple rabbinic readings (b. Sanhedrin 52a, Lev. Rabbah 20) blame various offences from drunkenness to spiritual ambition. The narrative leaves the offence deliberately under-specified; the lesson concerns the unmediated proximity of divine holiness, not the cataloguing of a particular sin.",
        "User original",
    ),
