        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>RANGES</strong> (1.) Leviticus 11:35. Probably a cooking furnace for two or more pots, as the Hebrew word here is in the dual number; or perhaps a fire-place fitted to receive a pair of ovens. (2.) 2 Kings 11:8. A Hebrew word is here used different from the preceding, meaning “ranks of soldiers.” The Levites were appointed to guard the king’s person within the temple (2 Chronicles 23:7), while the soldiers were his guard in the court, and in going from the temple to the palace. The soldiers…",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
