        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BATHS T</strong> he use of the bath was very frequent among the Hebrews (Leviticus 14:8; Numbers 19:19, ect.). The high priest at his inauguration (Leviticus 8:6), and on the day of atonement, was required to bathe himself (16:4, 24). The “pools” mentioned in Nehemiah 3:15, 16, 2 Kings 20:20, Isaiah 22:11, John 9:7, were public bathing-places.",
