        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>MULE</strong> (Hebrews pered), so called from the quick step of the animal or its power of carrying loads. It is not probable that the Hebrews bred mules, as this was strictly forbidden in the law (Leviticus 19:19), although their use was not forbidden. We find them in common use even by kings and nobles (2 Samuel 18:9; 1 Kings 1:33; 2 Kings 5:17; Psalm 32:9). They are not mentioned, however, till the time of David, for the word rendered “mules” (R.V. correctly, “hot springs”) in Genesis…",
