        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BEARD T</strong> he mode of wearing it was definitely prescribed to the Jews (Leviticus 19:27; 21:5). Hence the import of Ezekiel’s (5:1-4) description of the “razor” i.e., the agents of an angry providence being used against the guilty nation of the Jews. It was a part of a Jew’s daily toilet to anoint his beard with oil and perfume (Psalm 133:2). Beards were trimmed with the most fastidious care (2 Samuel 19:24), and their neglet was an indication of deep sorrow (Isaiah 15:2; Jeremiah…",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
