        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BALANCE</strong> occurs in Leviticus 19:36 and Isaiah 46:6, as the rendering of the Hebrew kanch’, which properly means “a reed” or “a cane,” then a rod or beam of a balance. This same word is translated “measuring reed” in Ezekiel 40:3,5; 42:16-18. There is another Hebrew word, mozena’yim, i.e., “two poisers”, also so rendered (Daniel 5:27). The balances as represented on the most ancient Egyptian monuments resemble those now in use. A “pair of balances” is a symbol of justice and fair…",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
