        "a",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>FORNICATION</strong> in every form of it was sternly condemned by the Mosaic law (Leviticus 21:9; 19:29; Deuteronomy 22:20, 21, 23-29; 23:18; Exodus 22:16). (See ADULTERY.) But this word is more frequently used in a symbolical than in its ordinary sense. It frequently means a forsaking of God or a following after idols (Isaiah 1:2; Jeremiah 2:20; Ezekiel 16; Hos. 1:2; 2:1-5; Jeremiah 3:8,9).",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
