        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BLEMISH</strong> imperfection or bodily deformity excluding men from the priesthood, and rendering animals unfit to be offered in sacrifice (Leviticus 21:17-23; 22:19-25). The Christian church, as justified in Christ, is “without blemish” (Ephesians 5:27). Christ offered himself a sacrifice “without blemish,” acceptable to God (1 Peter 1:19).",
