        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>FIRST-FRUITS T</strong> he first-fruits of the ground were offered unto God just as the first-born of man and animals. The law required, (1.) That on the morrow after the Passover Sabbath a sheaf of new corn should be waved by the priest before the altar (Leviticus 23:5, 6, 10, 12; 2:12). (2.) That at the feast of Pentecost two loaves of leavened bread, made from the new flour, were to be waved in like manner (Leviticus 23:15, 17; Numbers 28:26). (3.) The feast of Tabernacles was an acknowledgement…",
