        "d",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>WILLOWS</strong> (1.) Hebrews ‘arabim (Leviticus 23:40; Job 40:22; Isaiah 15:7; 44:3, 4; Psalm 137:1, 2). This was supposed to be the weeping willow, called by Linnaeus Salix Babylonica, from the reference in Psalm 137. This tree is frequently found “on the coast, overhanging wells and pools. There is a conspicuous tree of this species over a pond in the plain of Acre, and others on the Phoenician plain.” There are several species of the salix in Palestine, but it is not indigenous to…",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
