        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>REDEEMER H</strong> ebrews goel; i.e., one charged with the duty of restoring the rights of another and avenging his wrongs (Leviticus 25:48, 49; Numbers 5:8; Ruth 4:1; Job 19:25; Psalm 19:14; 78:35, etc.). This title is peculiarly applied to Christ. He redeems us from all evil by the payment of a ransom (q.v.). (See REDEMPTION.)",
