        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JORDAN H</strong> ebrews Yarden, “the descender;” Arab. Nahr-esh-Sheriah, “the watering-place” the chief river of Palestine. It flows from north to south down a deep valley in the centre of the country. The name descender is significant of the fact that there is along its whole course a descent to its banks; or it may simply denote the rapidity with which it “descends” to the Dead Sea. It originates in the snows of Hermon, which feed its perennial fountains. Two sources are generally spoken…",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
