    (
        26,
        42,
        "",
        "I will remember",
        "word",
        "Hebrew",
        "Hebrew",
        "<strong>Zakhar again.</strong> The same verb that opened the Exodus story (Exod 2:24) closes this chapter. Even after exile and curse, divine remembering remains the operative mechanism of restoration. The structural rhyme — God remembers, God acts — is one of the Pentateuch’s deepest theological grammars.",
        "User original",
    ),
    # ---- expansion (May 2026) ----
    (
        2,
        13,
        "b",
        "the salt of the covenant",
        "comm-contextual",
        "Note",
        "Note",
        '<strong>Salt of the covenant.</strong> Salt as covenant-marker recurs in Num 18:19 ("a covenant of salt forever") and 2 Chr 13:5. Ancient Near Eastern parallels include shared meals sealed with salt as a sign of unbreakable bond — salt’s preservative quality stood in for permanence. Jesus in Mark 9:49–50 ("everyone will be salted with fire… have salt in yourselves") echoes the cultic-covenantal resonance, not just the table-seasoning sense.',
        "User original",
    ),
    (
        7,
        11,
        "",
        "the sacrifice of peace offerings",
        "word",
        "Hebrew",
        "Hebrew",
        '<strong>Zevaḥ sh’lamim (<em>זֶבַח</em> <em>שְׁלָמִים</em>).</strong> The "peace offering" or "well-being offering" — the only sacrifice whose meat returned to the worshipper for a communal meal (7:15). Root <em>shalom</em>: completeness, peace, well-being. Unlike the wholly-burnt <em>‘olah</em>, the <em>sh’lamim</em> created a shared table between God and worshipper, eaten in proximity to the sanctuary. Paul’s argument in 1 Cor 10:18 about "those who eat the sacrifices" being partners with the altar trades on this category.',
        "User original",
    ),
    (
        11,
        3,
        "b",
        "parts the hoof",
        "comm-rabbinic",
        "Note",
        "Note",
        "<strong>Kashrut criteria.</strong> The land-animal criterion is twofold: cloven-hoofed AND chewing the cud. Possible explanations have multiplied — hygienic (Maimonides), symbolic-categorical (Mary Douglas, <em>Purity and Danger</em>: holiness = wholeness within categories), economic (favoring herd animals), and theological (visible markers of Israelite distinctiveness). Douglas’s reading remains influential: the dietary rules instantiate a vision of divine order in which every creature belongs to a clean category, and anomalies (pig: cloven hoof but no cud; camel: cud but no proper cloven hoof) are excluded.",
        "User paraphrase; references Maimonides",
    ),
    (
        13,
        2,
        "",
        "a swelling in his body’s skin",
        "word",
        "Hebrew",
        "Hebrew",
        '<strong>Tzara‘at (<em>צָרַעַת</em>).</strong> Traditionally translated "leprosy," but the term covers a range of skin and surface conditions — including conditions of garments (13:47–59) and houses (14:33–53), which Hansen’s disease cannot affect. The framework is ritual-purity, not modern dermatology. The priest functions as a diagnostician of communal status, not as a physician. Naaman’s healing in 2 Kgs 5 and the Gospels’ leper-healings work within this framework, where the priest must <em>certify</em> the cleansing.',
        "User original",
    ),
    (
        17,
        11,
        "b",
        "For the life of the flesh is in the blood",
        "comm",
        "Note",
        "Note",
        '<strong>Blood, life, atonement.</strong> One of the most theologically charged verses in the Pentateuch. The verse links three things: blood = life (<em>nefesh</em>), life given on the altar effects atonement, the prohibition on consuming blood follows from blood’s sacral function. Hebrews 9:22 cites this principle ("without the shedding of blood there is no forgiveness"). The verse underwrites both Jewish ritual slaughter (<em>shechita</em>, which drains blood) and the Christian theology of the cross.',
        "User original",
    ),
    (
        18,
        5,
        "",
        "he shall live in them",
        "comm",
        "Note",
        "Note",
        '<strong>Live by them.</strong> The verse becomes a key New Testament proof-text in the law/grace debate. Paul cites it in Gal 3:12 and Rom 10:5 as expressing the "do this and live" logic of law-righteousness, contrasted with faith-righteousness. The rabbinic reading runs the opposite way: "live by them, and not die by them" (b. Yoma 85b) — the foundational rabbinic principle of <em>piku‘aḥ nefesh</em>, that almost any commandment may be set aside to save a life.',
        "User original",
    ),
    (
        19,
        9,
        "",
        "you shall not wholly reap the corners of your field",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>The gleaning laws.</strong> One of the earliest legislated welfare provisions in the ancient Near East. The corners (<em>pe’ah</em>) and the gleanings (<em>leqet</em>) belong by right to the poor and the foreigner — not as charity but as their portion of the harvest. The book of Ruth turns on this institution (Ruth 2:2–3). Modern Jewish practice retains <em>pe’ah</em> as a category, often translated into financial giving where the original agricultural form is impractical.",
        "User original",
    ),
    (
        20,
        2,
        "",
        "gives any of his offspring to Molech",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>Molech.</strong> A Canaanite/Phoenician deity associated with child sacrifice. The Tophet at Carthage (a Phoenician colony) has yielded thousands of cremation urns containing infant remains, providing physical evidence that such sacrifices were practiced. The Hebrew Bible’s denunciations of Molech worship (Lev 18:21, 20:2–5; 2 Kgs 23:10; Jer 7:31, 32:35) are not polemical fiction but reflect a real religious option in the ancient Near East that Israel’s legislation flatly prohibited. The location at Topheth in the Valley of Hinnom (<em>Gei Hinnom</em>) eventually generated the New Testament word <em>gehenna</em>.",
        "User original",
    ),
    (
        21,
        1,
        "",
        "A priest shall not defile himself for the dead",
        "comm-orthodox",
        "Note",
        "Note",
        "<strong>Priestly purity.</strong> The priestly class is held to a higher purity standard than ordinary Israelites: no contact with corpses except for the closest relatives (21:2–3), no marriage to divorced women (21:7), no bodily blemishes for the high priest (21:17–23). The rules are not moral but cultic-symbolic — the priesthood embodies the principle of wholeness that the sanctuary itself instantiates. Many of these provisions were carried over and adapted in early Christian and especially Eastern Orthodox clerical discipline.",
        "User original",
    ),
    (
        23,
        15,
        "",
        "count from the next day after the Sabbath",
        "comm",
        "Note",
        "Note",
        "<strong>Counting the Omer.</strong> The seven-week count from the second day of Passover to Shavuot (Pentecost). Still observed daily in Jewish liturgy. The festival on the fiftieth day, originally an agricultural first-fruits feast, became in rabbinic tradition the celebration of the giving of the Torah at Sinai. In the New Testament, the same fiftieth day becomes Pentecost (Acts 2) — the giving of the Spirit. The structural parallel between Torah-giving and Spirit-giving on the same calendar day is foundational to early Christian theology.",
        "User original",
    ),
    (
        25,
        8,
        "",
        "seven Sabbaths of years",
        "comm",
        "Note",
        "Note",
        '<strong>The Jubilee year.</strong> The fiftieth year of the cycle — slaves freed, debts forgiven, alienated land returned to original families (25:10). Jesus quotes Isa 61, which is itself a Jubilee text, in his Nazareth sermon (Luke 4:18–19). Whether Jubilee was ever consistently practiced historically is debated by scholars — the prophetic literature laments its non-observance (Jer 34). The Liberty Bell in Philadelphia bears the inscription from 25:10 ("proclaim liberty throughout the land"), one of the most-quoted Pentateuchal verses in American civic memory.',
        "User original",
    ),
    # ---- heavy-pass batch 1: Leviticus empties (5, 6, 9, 12, 14, 15, 22, 24, 27) ----
    (
        5,
        7,
        "",
        "two turtledoves, or two young pigeons",
        "comm",
        "Note",
        "Note",
        "<strong>The poor person’s offering.</strong> The chapter codifies a sliding-scale offering system: those who cannot afford a lamb may bring two birds; those who cannot afford even birds may bring a tenth of an ephah of fine flour (5:11). The provision is one of the OT’s clearest statements of cultic accommodation to economic reality — atonement is not gated by wealth, and the poorest Israelite has access to the same forgiveness as the wealthiest. Mary brings the two-bird offering after Jesus’ birth (Luke 2:24) — the explicit textual marker of the holy family’s poverty, and a deliberate Lukan signal connecting Jesus to the lowliest economic stratum of Israelite religious life. The verse is one of the OT roots of the principle, central to later prophetic and rabbinic ethics, that ritual obligations must be calibrated to capacity rather than imposed identically regardless of means.",
        "User original",
    ),
    (
        5,
        15,
        "",
        "sins unwittingly regarding Yahweh’s holy things",
        "comm",
        "Note",
        "Note",
        '<strong>The trespass offering.</strong> The <em>asham</em> ("trespass offering" or "guilt offering") covers a distinct category from the sin offering (<em>chattat</em>): unintentional violations of holy things — eating priestly food by mistake, withholding tithe by oversight, undervaluing a vow, etc. The offering required a ram of valuation plus a 20% restitution penalty (5:16) — the first OT articulation of restitution-plus-penalty as a moral-cultic principle. Isaiah 53:10 famously identifies the suffering servant’s soul as an <em>asham</em>, the first explicit OT use of the trespass-offering category for an interpretive theology of redemptive death. The chapter’s combination of restitution (returning what was taken plus penalty) with cultic atonement (the offering) creates a model — material amends plus spiritual reconciliation — that has shaped both Jewish penitential practice and Christian theology of repentance.',
        "User original",
    ),
    (
        6,
        13,
        "",
        "Fire shall be kept burning on the altar continually",
        "comm",
        "Note",
        "Note",
        '<strong>The perpetual fire.</strong> The chapter requires the altar fire — kindled originally by Yahweh himself (9:24, supernaturally) — to be maintained continuously, never extinguished. The provision encodes a theological principle: the human role is to preserve the divinely-given fire, not to generate it. Rabbinic tradition (m. Tamid 1:1) preserves elaborate procedures for the priestly night-watches that maintained the temple altar fire continuously through the Second Temple period. Christian liturgical tradition draws on the imagery: the perpetual sanctuary lamp before the Eucharistic reserve in Catholic and Orthodox churches descends conceptually from this verse, and Pentecostal theology of the "fire that does not go out" takes the chapter as paradigm. The verse is one of the OT’s clearest articulations of preservation-as-piety: religious fidelity is often less about generating new acts than refusing to let the originally-given gift die out.',
        "User original",
    ),
    (
        6,
        25,
        "",
        "the law of the sin offering",
        "comm",
        "Note",
        "Note",
        '<strong>The priests’ portion.</strong> The chapter specifies that the meat of the sin offering — except for the fat and the inwards burned on the altar — belongs to the priests. The provision is theologically dense: priests literally consume the sacrifice that bears the people’s sin, in the holy place, and in eating it they participate in the sin-bearing function of the cult. Hebrews 13:11–12 takes the verse as type for Christ’s suffering "outside the camp" (the sin offering whose body, in some specific cases, was burned outside the camp rather than eaten — Lev 4:11–12, 16:27 — distinguishing those grades of sin offering from the priest-eaten ones treated here). The arrangement combines economic provision (priests eat from offerings) with theological symbolism (priests bear sin by ingestion) in characteristic Levitical fashion, making the priestly office both materially supported and ritually freighted in the same act.',
        "User original",
    ),
    (
        9,
        7,
        "",
        "make atonement for yourself, and for the people",
        "comm",
        "Note",
        "Note",
        '<strong>The order of atonement.</strong> Moses’ instruction to Aaron at the inaugural sacrifice — atone for yourself first, then for the people — encodes a principle that runs through the entire OT and NT priesthood theology: the priest must be cleansed before he can mediate cleansing for others. The same principle drives the Day of Atonement procedure (Lev 16:6, 11), where Aaron sacrifices a bull for himself and his household before offering the goats for Israel. Hebrews 7:27 cites this exact sequence to argue Christ’s priestly superiority — unlike Aaron, Christ "had no need to offer up sacrifices first for his own sins, then for those of the people." The verse is the textual root of the Christological argument that the priest’s sinlessness is what makes the priestly sacrifice non-repeatable: where Aaron’s priestly cleansing requires daily renewal, Christ’s sinlessness allows once-for-all sacrifice. The OT pattern remains theological pre-condition for the NT argument.',
        "User original",
    ),
    (
        9,
        24,
        "",
        "Fire came out from before Yahweh",
        "comm",
        "Note",
        "Note",
        '<strong>The divine ignition.</strong> Yahweh himself kindles the inaugural altar fire — the same theophanic pattern that consumes Elijah’s offering on Carmel (1 Kgs 18:38) and David’s sacrifice at Araunah’s threshing floor (1 Chr 21:26), and that descends as Pentecostal flames in Acts 2:3. The pattern across these passages is consistent: the legitimate sanctuary is one where the fire comes from above, not from below. The Christian Pentecost narrative (Acts 2) draws explicitly on this OT pattern: the tongues of fire descending on the apostles inaugurate the church’s priestly-Spirit-bearing function in the same way Yahweh’s descended fire inaugurated the priestly cult here. The verse establishes a recurrent OT-NT theological motif: divine institution validates a worship-space by visible fire from heaven. The chapter’s placement (the inaugural sacrifice immediately preceding the Nadab-and-Abihu disaster of Lev 10) sets up the contrast between divinely-given fire (legitimate) and "strange fire" (deadly).',
        "User original",
    ),
    (
        12,
        6,
        "",
        "a  year old lamb",
        "comm",
        "Note",
        "Note",
        "<strong>The post-childbirth offering.</strong> The chapter requires a postpartum mother to bring a year-old lamb plus a turtledove or pigeon at the end of her purification period — forty days for a son, eighty for a daughter (12:4–5). The lamb is the burnt offering (worship-restoration); the bird is the sin offering (purification). The provision is the cultic context of Mary’s presentation in Luke 2:22–24, where she brings the poor person’s alternative (two birds) — the same chapter’s sliding-scale provision in Lev 12:8. The asymmetric purification periods (forty vs. eighty days for sons vs. daughters) are unexplained in the text and have generated centuries of speculation; modern feminist scholarship has read them as encoding patriarchal devaluation, while others read them as protective accommodation (longer rest period for the mother of a daughter who will eventually menstruate). The chapter’s blunt biological focus — bodily fluids, female purity, ritual impurity surrounding birth — reflects the OT’s general assumption that human biology is intrinsically connected to cultic status.",
        "User original",
    ),
    (
        12,
        8,
        "",
        "two turtledoves or two young pigeons",
        "comm",
        "Note",
        "Note",
        '<strong>Mary’s offering.</strong> The verse provides the explicit textual ground for the New Testament’s claim that the Holy Family was poor: Luke 2:24 records Mary bringing exactly this offering — "a pair of turtledoves or two young pigeons" — at Jesus’ presentation in the temple. Luke’s readers steeped in Septuagint Greek would have recognized the precise verbal echo of Lev 12:8. The detail is not incidental — Luke is building a sustained Christological argument about Jesus’ identification with the poor, and the choice of offering at Mary’s purification is the first concrete economic marker. Combined with the manger setting, the absence of a household for the visiting magi (Matt 2:11 a "house," but only after travel), and Joseph’s carpenter trade, the Lukan portrait is consistent. The verse is one of the OT’s small specific texts that becomes load-bearing in NT Christological reflection on the social location of the incarnation.',
        "User paraphrase; references Septuagint",
    ),
    (
        14,
        4,
        "",
        "two living clean birds, cedar wood, scarlet, and hyssop",
        "comm-patristic",
        "Note",
        "Note",
        '<strong>The cleansing-from-leprosy ritual.</strong> The chapter’s elaborate purification rite for the recovered "leper" (the Hebrew <em>tzara‘at</em> covers a range of skin conditions, not modern Hansen’s disease) involves two birds, cedar wood, scarlet thread, and hyssop — the same four cultic substances as the red-heifer ash ritual in Num 19. One bird is killed over running water; the other is dipped in the blood and released alive into the open field. The pattern — one death, one release, both required for purification — has been read typologically by Christian commentators (Augustine, Origen) as anticipating the death-and-resurrection of Christ. Beyond the typological reading, the ritual also functions sociologically: the released bird carries the impurity outward into uninhabited space, a scapegoat-style expulsion paralleling the Yom Kippur goat sent to Azazel (Lev 16:21–22). The chapter is one of the OT’s most procedurally elaborate rituals and one of its most theologically suggestive.',
        "User paraphrase; references Augustine, Origen",
    ),
    (
        14,
        7,
        "",
        "sprinkle on him who is to be cleansed from the leprosy seven times",
        "comm",
        "Note",
        "Note",
        "<strong>The seven sprinklings.</strong> The number seven recurs throughout the cleansing ritual — seven sprinklings of blood (here), seven days outside the tent (14:8), seven-day waiting period before re-examination — and across Levitical purification more broadly. Seven in OT cultic numerology signals completeness, divine order, and full repetition; the seven-fold sprinkling is not just abundant but theologically definitive. The same numerological pattern recurs in Christian sacramental practice: the threefold-trine (rather than seven-fold) baptismal pouring in early church practice, the seven sacraments of medieval Catholic theology, the seven words from the cross. The verse establishes one of the OT’s most-imitated ritual numerical patterns. Practically, the seven days outside the camp provided medical observation time — the same condition could clear up over a week — making the ritual function partially as ancient infectious-disease management combined with cultic restoration.",
        "User original",
    ),
    (
        15,
        19,
        "",
        "her impurity seven days",
        "comm-modern-critical",
        "Note",
        "Note",
        "<strong>The menstruation laws.</strong> The chapter places menstrual impurity within the same category as bodily-discharge impurities (15:1–18 covers male discharges; 15:19–24 menstrual; 15:25–30 abnormal female discharges). The seven-day impurity period for menstruation, plus the secondary impurity of objects she sits or lies on, organizes household life around the menstrual cycle in significant ways. The chapter is the textual root of the Jewish <em>niddah</em> tradition and its mikveh-bath of post-menstrual purification. Modern feminist OT scholarship has read the chapter from multiple angles — Phyllis Trible, Tikva Frymer-Kensky, and Jacob Milgrom each emphasize different aspects: the symmetric treatment of male and female bodily impurities (against the older view that the chapter targeted women specifically), the genuine social regulation of intimate space, and the chapter’s eventual transformation in rabbinic Judaism into a system that women themselves maintained as religiously meaningful. The verse continues to generate substantial scholarly and devotional discussion.",
        "User paraphrase; summarises Milgrom",
    ),
    (
        15,
        31,
        "",
        "separate the children of Israel from their uncleanness",
        "comm",
        "Note",
        "Note",
        '<strong>The chapter’s theological hinge.</strong> The verse provides the framing principle for the entire purity-system the chapter has just laid out: separation from uncleanness is not just hygiene or social regulation but specifically protection from defiling Yahweh’s tabernacle. The cult is the focal point at which impurity becomes deadly — "so they will not die in their uncleanness when they defile my tabernacle." The chapter’s logic is concentric: ordinary household impurity is manageable; the same impurity entering sacred space generates lethal consequence. Mary Douglas’s <em>Purity and Danger</em> (1966) made this chapter one of the foundational texts of modern anthropological-theological reflection on impurity systems. Christian theological appropriation has often dismissed the purity laws as superseded by the gospel; modern OT scholarship has tended to recover them as a coherent theology of holiness-by-distance, where ordinary life is sustained partly by maintaining buffers between everyday impurity and the cultic center. The verse encodes the principle the entire chapter has been illustrating.',
        "User original",
    ),
    (
        22,
        21,
        "",
        "it shall be perfect to be accepted",
        "comm",
        "Note",
        "Note",
        '<strong>The unblemished principle.</strong> The chapter requires that all peace-offerings be physically perfect — no blindness, fracture, mutilation, sores, scabs, or scars (22:22). The Hebrew <em>tamim</em> ("perfect, complete, unblemished") is the same term Noah is described by (Gen 6:9, "perfect in his generations") and the same term Christ is described by in 1 Pet 1:19 ("a lamb without blemish or defect"). The Christological appropriation of the unblemished-offering principle is one of the most sustained NT readings of OT cult — the Levitical requirement of physical perfection in the offering becomes the typological ground for the moral perfection of Christ as the one true offering. The OT provision also functions practically: an Israelite tempted to dispose of a defective animal by offering it at the sanctuary (rather than slaughter at home) is forbidden the option, preserving the integrity of cultic substance. The verse is one of the OT’s clearest demonstrations that ritual procedure and moral substance are not separable.',
        "User original",
    ),
    (
        22,
        32,
        "",
        "You shall not profane my holy name",
        "comm",
        "Note",
        "Note",
        '<strong>The holiness of the Name.</strong> The verse establishes the principle of <em>kiddush ha-Shem</em> ("sanctification of the Name") — and its negative counterpart <em>chillul ha-Shem</em> ("desecration of the Name") — that runs through the rest of OT and Jewish theology. Ezekiel’s long meditation on Yahweh’s reputation among the nations (Ezek 36:20–23) draws directly on this principle: Israel’s exile has profaned the divine name, and Yahweh will restore Israel for his name’s sake. The Lord’s Prayer’s opening petition ("hallowed be your name," Matt 6:9) is built on the same theological foundation. In rabbinic Judaism, <em>kiddush ha-Shem</em> becomes the framework for martyrdom theology: dying rather than violating Torah is the highest form of sanctifying the Name (b. Sanhedrin 74a). The verse is one of the OT’s most consequential single sentences, generating two and a half millennia of Jewish ethical-theological reflection on the relationship between divine reputation and Israelite conduct.',
        "User original",
    ),
    (
        24,
        5,
        "",
        "twelve cakes",
        "comm",
        "Note",
        "Note",
        '<strong>The bread of the Presence.</strong> Twelve loaves of fine flour, set on the golden table inside the holy place, replaced weekly by fresh bread, with the old loaves eaten by the priests in a holy place (24:8–9). The number twelve corresponds to the tribes; the weekly replacement maintains the offering as continuously present. David and his men eat this bread at Nob (1 Sam 21:1–6), an episode Jesus cites in defense of his disciples plucking grain on the Sabbath (Mark 2:25–26, Matt 12:3–4, Luke 6:3–4) — the showbread becomes Jesus’ paradigm-text for ritual law yielding to human need. The Hebrew <em>leḥem ha-panim</em> ("bread of the Presence") frames the bread as Yahweh’s table-fellowship with Israel — a perpetual visible sign of divine presence. The Christian Eucharistic tradition draws extensively on this OT institution: the perpetual reservation of the consecrated bread, the table-presence theology, the priestly consumption all have OT antecedents in the showbread procedure.',
        "User original",
    ),
    (
        24,
        14,
        "",
        "all who heard him lay their hands on his head",
        "comm",
        "Note",
        "Note",
        "<strong>The blasphemer’s execution.</strong> The chapter records the OT’s only narrative of capital punishment for blasphemy — and the procedure it institutes (the witnesses lay hands on the offender’s head before execution) becomes the standard Israelite procedure for capital cases. The hand-laying gesture is theologically charged: the witnesses transfer responsibility for the death from the community generally to themselves specifically. The same gesture appears in priestly ordination (Lev 8:14), in Joshua’s commissioning by Moses (Num 27:18), and in Christian sacramental ordination across the centuries — the gesture transmits authority and obligation simultaneously. The blasphemer’s execution also illustrates one of the OT’s most-discussed legal principles: the same law applies to native Israelite and resident alien (24:16, 22). The provision is one of the OT’s clearest articulations of equal application of capital law regardless of ethnic identity, an unusual position in ANE legal contexts where most law-codes had distinct procedures for the various social classes.",
        "User original",
    ),
