        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>WEIGHTS R</strong> educed to English troy-weight, the Hebrew weights were: (1.) The gerah (Leviticus 27:25; Numbers 3:47), a Hebrew word, meaning a grain or kernel, and hence a small weight. It was the twentieth part of a shekel, and equal to 12 grains. (2.) Bekah (Exodus 38:26), meaning “a half” i.e., “half a shekel,” equal to 5 pennyweight. (3.) Shekel, “a weight,” only in the Old Testament, and frequently in its original form (Genesis 23:15, 16; Exodus 21:32; 30:13, 15; 38:24-29, etc.). It…",
